const int STATUS_LED   = 2;
const int BUZZER_PIN   = 14;
const int ACTUATOR_PIN = 27;
const int TRIG_PIN = 25; const int ECHO_PIN = 26;

const float ALERT_THRESHOLD = 15.0; // Calibrate on your real hardware (cm)
unsigned long lastSampleMs = 0;
const unsigned long SAMPLE_INTERVAL_MS = 500;

float readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW); delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long d = pulseIn(ECHO_PIN, HIGH, 30000);
  return d == 0 ? -1.0 : d / 58.2;
}

void applyDecision(float reading) {
  bool triggered = (reading > 0 && reading < ALERT_THRESHOLD);
  digitalWrite(STATUS_LED, triggered ? HIGH : LOW);
  digitalWrite(BUZZER_PIN, triggered ? HIGH : LOW);
  digitalWrite(ACTUATOR_PIN, triggered ? HIGH : LOW);

  Serial.print("Project #17 | Reading: ");
  Serial.print(reading);
  Serial.print(" cm | Status: ");
  Serial.println(triggered ? "ACTION TRIGGERED" : "NORMAL");
}

